NEW_FILES = {'zoo_keeper/core/teller_line_forms.py': '"""teller_line\'s forms (1.137.0): what a bank\'s line says over its windows.\n\nPure -- no Blender. `recipes/teller_line.py` builds the counter, posts, header\nand glass; in the ``bank`` form it asks `bank_board` for the NAMEBOARD on the\nheader\'s public face (-Y, where the trays are): the bank\'s name across its top\nband and each window\'s number over its bay -- the walker\'s bank comps, a name\nover the line and a number on every window.\n\nTHE BOARD IS A PANEL, NOT A DECAL. A quad on the header\'s face would share its\nplane, and one hovering in front of it would float; so the header steps back\nby the board\'s thickness and the board fills the step, its art the front and\nits four edges the rim, with no back face -- `sign_box`\'s face, built the same\nway for the same census (1.37.0). The envelope is unchanged: the counter and\nthe end posts still run the full depth.\n\nTHE VARIANT IS THE DOOR SIGN\'S. `storefront_names.sign_for` names a bank\n``names[k % 4]`` in ``COLOURWAYS[(k // 7) % 4]``, ``k`` the crc32 of its\nbusiness; the line\'s sixteen variants are the four names in the four\ncolourways, ``variant_for(business)`` the one that sign picks, so a line\nstamped with it reads the name and colours over the bank\'s door.\n"""\nfrom __future__ import annotations\n\nfrom . import prims as P\nfrom . import price_pylon_forms as PY\nfrom . import storefront_names as SN\n\nFORMS = ("auto", "bank")\n#: The board\'s thickness, which the header steps back by.\nBOARD_T = 0.02\n#: How far the board stands in from the header\'s edges and the end posts, so\n#: no face of it lies in a face of theirs.\nBOARD_INSET = 0.01\n#: The shortest board that sets every word with its windows numbered, metres:\n#: measured off `paint` at the narrowest numbered line (two 1.0 m bays, a\n#: 1.78 m board), every bank name and the digits 8 and 9 -- unset at 0.29,\n#: set at 0.30. A board under it carries the name alone, which set from 0.17\n#: on the narrowest line of all (1.0 m). They move when `storefront_names`\'\n#: density, `MIN_CAP` or `RULE` / `PAD` here do.\nNUMBERED_MIN = 0.30\n#: The name\'s share of a numbered board; the numbers have the rest.\nNAME_SHARE = 0.52\n#: The bank form\'s header, metres: its board 0.43 m, the name about 17 cm\n#: tall and the numbers about 15. A design choice, not a minimum; the\n#: default line\'s 0.20 m header sets nothing at reading size. A first board\n#: of a name tile and a tile a number, each paying a sign\'s margins, needed\n#: 0.57 m and still set the name 9 cm tall on a 6 m line.\nBANK_HEADER = 0.45\n#: How far a middle post reaches up into a raised header: past its underside,\n#: so the two share no plane, and short of the board\'s lower edge, which\n#: stands `BOARD_INSET` above it -- at 0.02 the post\'s front ran 1 cm up the\n#: board\'s face, the one pair the bank form\'s first census found.\nPOST_INTO_HEADER = BOARD_INSET / 2.0\n\n\ndef bank_names():\n    for kind, _match, names in SN.KINDS:\n        if kind == "bank":\n            return names\n    raise ValueError("storefront_names has no bank kind")\n\n\ndef bank_said(variant):\n    """``{text, colours}``: the variant\'s bank name, ``variant % 4``, in its\n    colourway, ``variant // 4``."""\n    names = bank_names()\n    v = int(variant or 0)\n    return {"text": names[v % len(names)], "colours": PY.COLOURWAYS[(v // len(names)) % len(PY.COLOURWAYS)]}\n\n\ndef variant_for(business):\n    """The variant whose name and colours are the ones `storefront_names.\n    sign_for` puts over ``business``\'s door: what Deli Counter stamps on a\n    bank\'s teller slot."""\n    k = SN.key(business)\n    return k % len(bank_names()) + len(bank_names()) * ((k // 7) % len(PY.COLOURWAYS))\n\n\n#: The line\'s variants: every name in every colourway.\nVARIANTS = 4 * len(PY.COLOURWAYS)\n\n\ndef header_of(header, h, counter_h):\n    """The bank form\'s header height: `BANK_HEADER`, never less than the\n    genome\'s, never more than half the space above the counter."""\n    return min(max(float(header), BANK_HEADER), (h - counter_h) * 0.5)\n\n\ndef bank_board(w, d, h, post, header, runs, variant):\n    """``(prims, tiles)`` for the nameboard: one art quad (``tile`` set) and a\n    rim, in the recipe\'s frame (centre pivot, public face at -Y); ``runs``\n    are `_bays.bays`\' ``(x_centre, width)``. One bay carries the name alone;\n    more carry the name over a number a bay -- when the board is tall enough\n    for both bands, and the name alone on a line too short for them."""\n    hw, hh = w / 2.0, h / 2.0\n    x0, x1 = -hw + post + BOARD_INSET, hw - post - BOARD_INSET\n    z0, z1 = hh - header + BOARD_INSET, hh - BOARD_INSET\n    y0, y1 = -d / 2.0, -d / 2.0 + BOARD_T\n    said = bank_said(variant)\n    numbered = len(runs) >= 2 and z1 - z0 >= NUMBERED_MIN\n    numbers = []\n    if numbered:\n        numbers = [((min(x1, max(x0, bx)) - x0) / (x1 - x0), str(i + 1)) for i, (bx, _bw) in enumerate(runs)]\n    quad_uv = [((0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0))]\n    art = P.mesh("TellerLine_BoardFace", "art", [(x0, y0, z0), (x1, y0, z0), (x1, y0, z1), (x0, y0, z1)],\n                 [(0, 1, 2, 3)])\n    art["tile"] = "board"\n    art["uvs"] = list(quad_uv)\n    rim = P.box("TellerLine_BoardRim", "art", (x0, y0, z0), (x1, y1, z1))\n    # the box\'s bottom, top and two ends; its front is the art, and it has\n    # no back -- that would lie in the header\'s stepped face\n    rim["faces"] = [f for k, f in enumerate(rim["faces"]) if k in (0, 1, 3, 5)]\n    rim["tile"] = "edge"\n    rim["uvs"] = list(quad_uv) * len(rim["faces"])\n    tiles = {"board": {"kind": "teller_board", "w_m": x1 - x0, "h_m": z1 - z0, "text": said["text"],\n                       "colours": said["colours"], "voice": SN.voice_for("bank"), "numbers": numbers,\n                       "bay_m": min(bw for _bx, bw in runs)},\n             "edge": {"kind": "storefront_sign", "w_m": 0.1, "h_m": 0.1, "edge": True,\n                      "text": "", "colours": said["colours"]}}\n    return [art, rim], tiles\n\n\n#: The board\'s one rule top and bottom, and the rule between its bands, in\n#: painted px; the pad every word keeps from a rule or an edge.\nRULE = 2\nPAD = 1\n\n\ndef paint(spec):\n    """The board as a Canvas (`card_art`\'s ``teller_board`` kind): the field,\n    a rule top and bottom, the name as large as it sets across the top band,\n    and under a rule each window\'s number centred on its bay. One tile and\n    one set of rules, where a name tile and a tile a number paid a sign\'s\n    margins each and set the name 9 cm tall on a 6 m line. ``c.unset`` lists\n    every word that did not set."""\n    from . import paint as PT\n    D, O = SN.DENSITY, SN.OUTLINE\n    tx = SN.TEXEL * D\n    w = max(8, int(round(spec["w_m"] * tx)))\n    h = max(8, int(round(spec["h_m"] * tx)))\n    field, rule, ink = (tuple(x) for x in spec["colours"])\n    img = PT.Img(w, h, field)\n    r, pad = RULE * D, PAD * D\n    img.rect((0, 0, w, r), rule)\n    img.rect((0, h - r, w, h), rule)\n    numbers = spec.get("numbers") or []\n    split = h - r\n    if numbers:\n        split = int(round(h * NAME_SHARE))\n        img.rect((0, split - r // 2, w, split - r // 2 + r), rule)\n\n    def word(text, cx, top, bottom, box_w):\n        face, cap, lines = SN.layout(text, box_w - 2 * pad - 2 * O, bottom - top - 2 * pad - 2 * O,\n                                     spec.get("voice", "shop"))\n        if not cap:\n            img.unset.append(text)\n            return\n        cov = SN._block(lines, cap, face)\n        x = int(round(cx - cov.shape[1] / 2.0))\n        y = top + (bottom - top - cov.shape[0]) // 2\n        img.mask(SN._grow(cov, O), x - O, y - O, rule)\n        img.mask(cov, x, y, ink)\n\n    word(spec["text"], w / 2.0, r, split - r // 2, w)\n    bay = int(round(spec.get("bay_m", spec["w_m"]) * tx))\n    for frac, text in numbers:\n        word(text, frac * w, split - r // 2 + r, h - r, min(bay, w))\n    return img.to_canvas()\n', 'tests/test_teller_line_bank.py': '"""teller_line\'s bank form (1.137.0): the nameboard (pure -- no Blender).\n\nThe board names the bank over the line and numbers each window; these hold\nthat every word on it sets at the size it is painted (through `card_art`\'s\nown dispatch), that it stays inside the module\'s envelope on the header\'s\npublic face, and that its threshold is the one `teller_line_forms` measured.\n"""\nimport pytest\n\nfrom zoo_keeper.core import card_art as CA\nfrom zoo_keeper.core import genome\nfrom zoo_keeper.core import kit\nfrom zoo_keeper.core import storefront_names as SN\nfrom zoo_keeper.core import teller_line_forms as TF\nfrom zoo_keeper.recipes._bays import bays\n\n#: the genome\'s corners and lines between: one bay, two, four, six; and the\n#: three the library\'s banks build (Deli Counter 0.282.0\'s slots)\nLINES = [(1.0, 0.3, 2.0), (2.0, 0.5, 3.0), (2.01, 0.5, 2.0), (7.5, 0.6, 3.2), (12.0, 1.2, 4.0),\n         (12.0, 0.8, 2.4), (10.0, 0.9, 2.4), (8.0, 0.8, 2.4)]\n\n\ndef _board(w, d, h, variant=0):\n    g = genome.load_species("teller_line")\n    p = {k: (v["default"] if isinstance(v, dict) else v) for k, v in g["params"].items()}\n    counter_h = min(p["counter_h"], h * 0.6)\n    post = min(p["post"], w * 0.3)\n    header = TF.header_of(min(p["header"], (h - counter_h) * 0.5), h, counter_h)\n    runs = bays(w, p["bay_max"])\n    return TF.bank_board(w, d, h, post, header, runs, variant), runs, post, header\n\n\ndef _numbered(h_m, said):\n    return {"kind": "teller_board", "w_m": 1.78, "h_m": h_m, "text": said["text"], "colours": said["colours"],\n            "voice": "shop", "numbers": [(0.25, "8"), (0.75, "9")], "bay_m": 0.89}\n\n\ndef test_the_genome_offers_the_bank_form_and_a_name_a_variant():\n    g = genome.load_species("teller_line")\n    assert g["params"]["form"] == list(TF.FORMS)\n    assert g["module_variants"] == TF.VARIANTS == 16\n    got, why = kit.honour_dressing({"form": "bank", "variant": 15}, "teller_line")\n    assert got == {"form": "bank", "stock": None, "variant": 15} and not why\n\n\ndef test_a_bank_line_reads_its_door_sign():\n    """`variant_for` is the variant whose name and colours `sign_for` puts\n    over the door -- for every bank in the library and a run of made-up ones."""\n    names = ["bank_branch_a0%d" % i for i in range(1, 8)] + ["lf_bank_block_001_%d bank" % s for s in range(40)]\n    seen = set()\n    for business in names:\n        sign = SN.sign_for(business)\n        assert sign["kind"] == "bank", business\n        v = TF.variant_for(business)\n        assert 0 <= v < TF.VARIANTS\n        said = TF.bank_said(v)\n        assert said["text"] == sign["text"] and tuple(said["colours"]) == tuple(sign["colours"]), business\n        seen.add(v)\n    assert len(seen) > 8, seen\n\n\n@pytest.mark.parametrize("w,d,h", LINES)\n@pytest.mark.parametrize("variant", range(16))\ndef test_every_word_on_the_board_sets(w, d, h, variant):\n    (_prims, tiles), runs, _post, _header = _board(w, d, h, variant)\n    board = tiles["board"]\n    assert board["text"] == TF.bank_names()[variant % 4]\n    assert [n for _f, n in board["numbers"]] == ([] if len(runs) < 2 else [str(i + 1) for i in range(len(runs))])\n    c = CA.paint(board)\n    assert not c.unset, (w, h, variant, c.unset)\n\n\n@pytest.mark.parametrize("w,d,h", LINES)\ndef test_the_board_is_inside_the_envelope_on_the_public_face(w, d, h):\n    (prims, tiles), runs, post, header = _board(w, d, h)\n    art, rim = prims\n    for q in prims:\n        for x, y, z in q["verts"]:\n            assert -w / 2 + post < x < w / 2 - post, (q["part"], x)\n            assert -d / 2 - 1e-9 <= y <= -d / 2 + TF.BOARD_T + 1e-9, (q["part"], y)\n            assert h / 2 - header < z < h / 2, (q["part"], z)\n    # the art faces the trays, on the front plane, and is the rim\'s front\n    assert all(abs(y + d / 2) < 1e-9 for _x, y, _z in art["verts"])\n    assert {(x, z) for x, _y, z in art["verts"]} == {(x, z) for x, y, z in rim["verts"] if abs(y + d / 2) < 1e-9}\n    # no back face: the rim keeps its bottom, top and ends\n    assert len(rim["faces"]) == 4\n    # each number sits over its own bay\n    x0 = -w / 2 + post + TF.BOARD_INSET\n    for (frac, _n), (bx, _bw) in zip(tiles["board"]["numbers"], runs):\n        assert abs(x0 + frac * tiles["board"]["w_m"] - bx) < 1e-9\n\n\ndef test_a_board_too_short_for_both_bands_carries_the_name_alone():\n    # unreachable inside the genome\'s ranges, which never leave a board under\n    # NUMBERED_MIN; held here so the fallback is not a branch nobody runs\n    runs = bays(4.0, 2.0)\n    _prims, tiles = TF.bank_board(4.0, 0.5, 3.0, 0.1, TF.NUMBERED_MIN, runs, 0)\n    assert tiles["board"]["numbers"] == []\n    assert not CA.paint(tiles["board"]).unset\n    _prims, tiles = TF.bank_board(4.0, 0.5, 3.0, 0.1, TF.NUMBERED_MIN + 2 * TF.BOARD_INSET, runs, 0)\n    assert len(tiles["board"]["numbers"]) == 2\n\n\n@pytest.mark.parametrize("variant", range(4))\ndef test_the_measured_threshold_is_the_one_paint_keeps(variant):\n    """`NUMBERED_MIN` is where the narrowest numbered board first sets every\n    word; a centimetre under it, one does not."""\n    said = TF.bank_said(variant)\n    assert not CA.paint(_numbered(TF.NUMBERED_MIN, said)).unset\n    assert CA.paint(_numbered(TF.NUMBERED_MIN - 0.01, said)).unset\n\n\ndef test_the_bank_header_is_raised_but_never_past_half_the_opening():\n    assert TF.header_of(0.2, 3.0, 1.1) == TF.BANK_HEADER\n    assert TF.header_of(0.2, 2.0, 1.2) == pytest.approx(0.4)\n    assert TF.header_of(0.5, 3.0, 1.1) == 0.5\n\n\ndef test_a_middle_post_stops_inside_the_header_and_under_the_board():\n    """At 0.02 a middle post\'s front ran 1 cm up the board\'s face, the one\n    coincident pair the bank form\'s first census found."""\n    assert 0.0 < TF.POST_INTO_HEADER < TF.BOARD_INSET\n\n'}
CHANGELOG = '## [1.137.0] - a bank\'s printed offers and its name over the teller line\n\nThe walker\'s bank list, after the cameras, walls and plants: "the rate board and posters", then the bank\'s name over the\nline and a number on every window (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md, comps 2, 4 and 7; roadmap 321).\nThe library had neither: a bank\'s walls could carry only a club\'s, a bar\'s, an alley\'s or a store\'s sheets, and every\nteller line was a plain grey frame.\n\n### Added\n- **`poster_wall` form `bank`**: a bank lobby\'s printed offers, 0.46 x 0.62 m, hung square 0.30 m apart.\n  - Twelve offers, each with one big figure: XMAS CLUB / JOIN, FREE CHECKING / $0, CD RATES / 5.65%, HOME EQUITY /\n    7.9%, AUTO LOANS / 8.5%, SAT HOURS / 9-12, NEW ACCOUNT / FREE, ATM CARDS / 24 HR, PASSBOOK / 2.5%, LOW RATES /\n    6.9%, NIGHT DROP / 3 PM, and RATES TODAY.\n  - A sheet is the bank\'s band across the top, the offer, its figure on a panel, and the fine print on a white strip.\n    The figure is white on the bank\'s colour on plain paper, and dark on white on loud.\n  - **RATES TODAY is the rate board**: five products and their yields (PASSBOOK, CD 6 MO, CD 1 YR, CD 5 YR, IRA).\n    It is white letters on black felt on plain paper, and black letters on a white letterboard on the bank\'s colour.\n  - One palette a wall (the wall\'s key), so one lobby\'s sheets are one bank\'s. Four palettes: navy, maroon, green, blue.\n  - THE FLAW: the lower right corner has curled off its tape.\n- **`teller_line` form `bank`**, its sixteen variants `storefront_names`\' four bank names (FIRST DELCO SAVINGS, PIKE\n  SAVINGS & LOAN, MATTRESS MONEY TRUST, YOUSE CREDIT CO-OP) in the sign pylon\'s four colourways.\n  - **The variant is the door sign\'s.** `teller_line_forms.variant_for(business)` is the variant whose name and colours\n    `storefront_names.sign_for` puts over that bank\'s door. Deli Counter stamps it, so the line names the bank its\n    sign does.\n  - A NAMEBOARD on the header\'s public face: the bank\'s name across its top band, and each window\'s number centred\n    over its bay, under a rule. A line of one bay carries the name alone.\n  - The header rises to 0.45 m (`teller_line_forms.BANK_HEADER`). It steps back by the board\'s 2 cm and the board\n    fills the step, so the envelope is unchanged. The board is an art front and four edges with no back face,\n    `sign_box`\'s face built the same way.\n  - The middle posts stop 5 mm inside the raised header, under the board\'s lower edge.\n  - One painted atlas (`card_art` kind `teller_board`, `teller_line_forms.paint`), so one material more a line.\n    +10 tris on a one-bay line, +10 on six bays (the art quad and its rim).\n  - The default form is the line it always was.\n\n### Measured\n- **A rate line that does not fit sets nothing.** `fit_text` returns None and draws nothing. A MONEY MKT line did that,\n  and then, with its column widened, every rate at the shipped 118 px. The three poster tests passed that board. The\n  painter now reports each line, and a test holds it.\n- **The nameboard\'s thresholds are measured, not chosen**, off the painter at `storefront_names`\' 80 px a metre and\n  `MIN_CAP` 12.\n  - The narrowest numbered board (two 1.0 m bays, 1.78 m) sets every word from 0.30 m, and not at 0.29.\n  - A name alone sets from 0.17 m on a 1.0 m line.\n- **A first board was a name tile and a tile a number**, each with a sign\'s margins and two rules. It needed a 0.57 m\n  header and still set the name 9 cm tall on a 6 m line. The number thresholds were first measured on "1" alone, which\n  lost every "3". The one-tile board sets the name about 17 cm and the numbers about 15 on a 0.43 m board.\n- **Census** (`tools/coplanar_census.py`\'s loop, every slot dressed form `bank`, variant 1): 13, 13 and 63 pairs at the\n  min, default and max corners, against the plain line\'s 13, 13 and 88. None involves the board. The 13 are the\n  line\'s own touching boxes and are unchanged. The max corner loses 15 because its middle posts no longer reach the\n  header\'s top.\n  - The first census found one pair: a middle post\'s front 1 cm up the board\'s face, at 2 cm into the header.\n\n### Tests\n- `tests/test_poster_wall.py`: the bank family is in every family test.\n  - Its sheets pass the three tests: the headline at 5 m, the focal image off its ground, the mass.\n  - Both stocks: plain paper is plain, loud is not, and an unknown stock is refused.\n  - Every product and rate on the board sets at the size it ships.\n- New `tests/test_teller_line_bank.py`:\n  - the form and sixteen variants are honoured;\n  - a line reads its door sign: seven library banks and forty made-up ones;\n  - every name and number sets at five lines across the genome\'s range;\n  - the board is inside the envelope on the public face, with each number over its bay;\n  - the name-alone fallback;\n  - the measured threshold;\n  - the header\'s clamp;\n  - the post under the board.\n\n'
OLD_VERSION, NEW_VERSION = '1.136.0', '1.137.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
